\draw[line width=0.4pt] (0,7)--(yinterceptlabel.east);
\draw[line width=0.4pt] ({(3-sqrt(23))/2},0)--(leftrootlabel.east);
\draw[line width=0.4pt] ({(3+sqrt(23))/2},0)--(rightrootlabel.west);
